14	 * 过渡纸卷仓储。
15	 */
16	@Repository
17	public class TransitionRollRepository {
18	
19	    private static final RowMapper<TransitionRoll> MAPPER = (rs, n) -> {
20	        TransitionRoll r = new TransitionRoll();
21	        r.setId(rs.getLong("id"));
22	        r.setRollNo(rs.getString("roll_no"));
23	        r.setOrderNo(rs.getString("order_no"));
24	        r.setPaperMachine(rs.getString("paper_machine"));
25	        r.setLengthM(rs.getBigDecimal("length_m"));
26	        r.setVerdict(rs.getString("verdict"));
27	        r.setWarehouseStatus(rs.getString("warehouse_status"));
28	        r.setEligibleReexam(rs.getInt("eligible_reexam") != 0);
29	        r.setReexamCount(rs.getInt("reexam_count"));
30	        r.setRegisteredAt(rs.getTimestamp("registered_at").toLocalDateTime());
31	        Timestamp changed = rs.getTimestamp("verdict_changed_at");
32	        r.setVerdictChangedAt(changed == null ? null : changed.toLocalDateTime());
33	        return r;
34	    };
35	
36	    private final JdbcTemplate jdbc;
37	
38	    public TransitionRollRepository(JdbcTemplate jdbc) {
39	        this.jdbc = jdbc;
40	    }
41	
42	    /** 强制降级登记：verdict=DOWNGRADED，warehouse_status=NON_GENUINE。 */
43	    public void insertDowngraded(TransitionRoll roll, LocalDateTime now) {
44	        jdbc.update("""
45	                        INSERT INTO transition_roll
46	                            (roll_no, order_no, paper_machine, length_m, verdict,
47	                             warehouse_status, eligible_reexam, reexam_count, registered_at)
48	                        VALUES (?, ?, ?, ?, 'DOWNGRADED', 'NON_GENUINE', 0, 0, ?)
49	                        """,
50	                roll.getRollNo(), roll.getOrderNo(), roll.getPaperMachine(),
51	                roll.getLengthM(), Timestamp.valueOf(now));
52	    }
53	
54	    public Optional<TransitionRoll> findByRollNo(String rollNo) {
55	        List<TransitionRoll> list = jdbc.query(
56	                "SELECT * FROM transition_roll WHERE roll_no = ?", MAPPER, rollNo);
57	        return list.stream().findFirst();
58	    }
59	
60	    public TransitionRoll getByRollNo(String rollNo) {
61	        return findByRollNo(rollNo).orElseThrow(() ->
62	                new IllegalArgumentException("过渡纸卷不存在: " + rollNo));
63	    }
64	
65	    public List<TransitionRoll> findByOrderNo(String orderNo) {
66	        return jdbc.query(
67	                "SELECT * FROM transition_roll WHERE order_no = ? ORDER BY id",
68	                MAPPER, orderNo);
69	    }
70	
71	    /** 首次检验回写复议资格，不改判定（仍为降级）。 */
72	    public void updateInitialEligibility(String rollNo, boolean eligible) {
73	        jdbc.update("UPDATE transition_roll SET eligible_reexam = ? WHERE roll_no = ?",
74	                eligible ? 1 : 0, rollNo);
75	    }
76	
77	    /** 复议改判：终态 UPGRADED、入正品库、复议次数 +1。 */
78	    public int applyUpgrade(String rollNo, LocalDateTime now) {
79	        return jdbc.update("""
80	                        UPDATE transition_roll
81	                        SET verdict = 'UPGRADED', warehouse_status = 'GENUINE',
82	                            reexam_count = reexam_count + 1, verdict_changed_at = ?
83	                        WHERE roll_no = ? AND verdict = 'DOWNGRADED' AND reexam_count = 0
84	                        """,
85	                Timestamp.valueOf(now), rollNo);
86	    }
87	
88	    /** 复议驳回：仅复议次数 +1，终态保持降级、留非正品库。 */
