29	import java.util.concurrent.TimeUnit;
30	import java.util.concurrent.atomic.AtomicInteger;
31	import java.util.stream.IntStream;
32	
33	import static org.junit.jupiter.api.Assertions.assertEquals;
34	import static org.junit.jupiter.api.Assertions.assertTrue;
35	
36	/**
37	 * 掺配比例真实并发 H2 测试：同一订单同时刻只允许一次执行中调整、
38	 * 读数按订单与采样时刻并发去重、同键并发重放。
39	 */
40	@Import(AbstractIntegrationTest.FixedClockConfiguration.class)
41	class BlendRatioConcurrencyTest extends AbstractIntegrationTest {
42	
43	    private static final int THREADS = 5;
44	    private static final LocalDateTime SAMPLED_AT = LocalDateTime.of(2026, 9, 25, 11, 0, 0);
45	
46	    @Autowired
47	    private TransitionService service;
48	    @Autowired
49	    private JdbcTemplate jdbc;
50	
51	    @BeforeEach
52	    void clean() {
53	        cleanBusinessTables(jdbc);
54	    }
55	
56	    @Test
57	    @DisplayName("并发执行中调整同一订单（固定时钟同时刻）：唯一受理，其余409，版本链只增一档")
58	    void concurrentAdjustSameTimeOnlyOneAccepted() throws Exception {
59	        String orderNo = prepareExecutedOrder("cc-adj", "PM-CB1");
60	
61	        CyclicBarrier barrier = new CyclicBarrier(THREADS);
62	        AtomicInteger success = new AtomicInteger();
63	        AtomicInteger conflict = new AtomicInteger();
64	        runConcurrently(THREADS, i -> {
65	            barrier.await(10, TimeUnit.SECONDS);
66	            service.adjustBlendRatio(orderNo,
67	                    new AdjustBlendRatioRequest("cc-adj-" + i, new BigDecimal("20.000")));
68	            success.incrementAndGet();
69	        }, ex -> {
70	            if (ex instanceof ApiException api && api.getStatus() == 409) {
71	                conflict.incrementAndGet();
72	            } else {
73	                throw new AssertionError("非预期异常", ex);
74	            }
75	        });
76	
77	        assertEquals(1, success.get(), "同时刻只允许一次执行中调整");
78	        assertEquals(THREADS - 1, conflict.get());
79	        assertEquals(2L, jdbc.queryForObject(
80	                "SELECT COUNT(1) FROM blend_ratio_version WHERE order_no = ?", Long.class, orderNo),
81	                "APPLY v1 + ADJUST v2，并发不产生重复版本");
82	        assertEquals(2, service.getOrder(orderNo).currentBlendVersion());
83	    }
84	
85	    @Test
86	    @DisplayName("并发提交同一订单同一采样时刻读数：唯一登记，其余409，最终仅一条读数")
87	    void concurrentReadingSameSampledAtDeduplicated() throws Exception {
88	        String orderNo = prepareExecutedOrder("cc-rd", "PM-CB2");
89	
90	        CyclicBarrier barrier = new CyclicBarrier(THREADS);
91	        AtomicInteger success = new AtomicInteger();
92	        AtomicInteger conflict = new AtomicInteger();
93	        runConcurrently(THREADS, i -> {
94	            barrier.await(10, TimeUnit.SECONDS);
95	            service.submitBlendReading(new BlendReadingRequest(
96	                    "cc-rd-" + i, orderNo, SAMPLED_AT, new BigDecimal("21.000")));
97	            success.incrementAndGet();
98	        }, ex -> {
99	            if (ex instanceof ApiException api && api.getStatus() == 409) {
100	                conflict.incrementAndGet();
101	            } else {
102	                throw new AssertionError("非预期异常", ex);
103	            }
104	        });
105	
106	        assertEquals(1, success.get(), "同一订单同一采样时刻只登记一条读数");
107	        assertEquals(THREADS - 1, conflict.get());
108	        assertEquals(1L, jdbc.queryForObject(
109	                "SELECT COUNT(1) FROM blend_reading WHERE order_no = ?", Long.class, orderNo));
110	    }
111	
112	    @Test
113	    @DisplayName("同键同参并发调整：唯一受理，其余重放首次结果，版本链只增一档")
114	    void concurrentSameRequestIdAdjustYieldsSingleAccept() throws Exception {
115	        String orderNo = prepareExecutedOrder("cc-key", "PM-CB3");
116	
117	        CyclicBarrier barrier = new CyclicBarrier(THREADS);
118	        AtomicInteger created = new AtomicInteger();
119	        AtomicInteger replayed = new AtomicInteger();
120	        runConcurrently(THREADS, i -> {
121	            barrier.await(10, TimeUnit.SECONDS);
122	            IdempotentResult<BlendVersionView> result = service.adjustBlendRatio(orderNo,
123	                    new AdjustBlendRatioRequest("cc-same-key", new BigDecimal("20.000")));
124	            if (result.replayed()) {
125	                replayed.incrementAndGet();
126	            } else {
127	                created.incrementAndGet();
128	            }
129	        }, ex -> {
130	            throw new AssertionError("同键同参并发不应抛异常", ex);
131	        });
132	
133	        assertEquals(1, created.get());
134	        assertEquals(THREADS - 1, replayed.get());
135	        assertEquals(2L, jdbc.queryForObject(
136	                "SELECT COUNT(1) FROM blend_ratio_version WHERE order_no = ?", Long.class, orderNo));
137	    }
138	
139	    @Test
140	    @DisplayName("并发提交触发失控的第3个超差读数：暂停转人工只发生一次")
141	    void concurrentOutOfControlPauseHappensOnce() throws Exception {
142	        String orderNo = prepareExecutedOrder("cc-pause", "PM-CB4");
143	        // 先累计 2 个连续超差点
144	        service.submitBlendReading(new BlendReadingRequest(
145	                "cc-p1", orderNo, SAMPLED_AT, new BigDecimal("28.000")));
146	        service.submitBlendReading(new BlendReadingRequest(
147	                "cc-p2", orderNo, SAMPLED_AT.plusMinutes(1), new BigDecimal("28.000")));
148	
149	        // 并发提交第 3 个超差点（不同时刻避免去重干扰）：失控暂停只登记一次
150	        CyclicBarrier barrier = new CyclicBarrier(THREADS);
151	        AtomicInteger submitted = new AtomicInteger();
152	        runConcurrently(THREADS, i -> {
153	            barrier.await(10, TimeUnit.SECONDS);
154	            IdempotentResult<BlendReadingView> result = service.submitBlendReading(
155	                    new BlendReadingRequest("cc-p3-" + i, orderNo,
156	                            SAMPLED_AT.plusMinutes(2 + i), new BigDecimal("28.500")));
157	            if (!result.replayed()) {
158	                submitted.incrementAndGet();
159	            }
160	        }, ex -> {
161	            // 先失控暂停的事务提交后，其余读数因 PAUSED 被拒 409，属预期
162	            if (!(ex instanceof ApiException api && api.getStatus() == 409)) {
163	                throw new AssertionError("非预期异常", ex);
164	            }
165	        });
166	
167	        assertTrue(submitted.get() >= 1, "至少一个读数触发失控");
168	        assertEquals(TransitionStatus.PAUSED, service.getOrder(orderNo).status());
169	        assertEquals(1L, jdbc.queryForObject(
170	                "SELECT COUNT(1) FROM blend_control_event WHERE order_no = ? AND event_type = 'OUT_OF_CONTROL_PAUSE'",
171	                Long.class, orderNo), "失控暂停转人工事件唯一");
172	    }
173	
174	    // ------------------------------------------------------------------
175	    // 测试辅助
176	    // ------------------------------------------------------------------
177	
178	    /** 申请携带比例（同事务判定）并执行，返回 EXECUTED 状态单号。 */
179	    private String prepareExecutedOrder(String requestId, String machine) {
180	        OrderView applied = service.apply(new ApplyOrderRequest(
181	                requestId, machine, "G-A4-70", "G-A4-77", new BigDecimal("25.000"))).data();
182	        assertEquals(TransitionStatus.DECIDED, applied.status());
183	        return service.execute(applied.orderNo(), new ExecuteOrderRequest(
184	                new BigDecimal("900.000"), new BigDecimal("1.000"), 60)).orderNo();
185	    }
186	
187	    private void runConcurrently(int threads, ConcurrentAction action, ErrorHandler handler)
188	            throws Exception {
189	        ExecutorService pool = Executors.newFixedThreadPool(threads);
190	        try {
191	            List<Future<Void>> futures = IntStream.range(0, threads)
192	                    .mapToObj(i -> (java.util.concurrent.Callable<Void>) () -> {
193	                        try {
194	                            action.run(i);
195	                        } catch (BrokenBarrierException | InterruptedException e) {
196	                            throw new AssertionError("并发同步失败", e);
197	                        } catch (Exception e) {
198	                            handler.handle(e);
199	                        }
200	                        return null;
201	                    })
202	                    .map(pool::submit)
203	                    .toList();
204	            for (Future<?> future : futures) {
205	                future.get(30, TimeUnit.SECONDS);
206	            }
207	        } finally {
208	            pool.shutdownNow();
209	            assertTrue(pool.awaitTermination(10, TimeUnit.SECONDS));
210	        }
211	    }
212	
213	    @FunctionalInterface
214	    private interface ConcurrentAction {
215	        void run(int index) throws Exception;
216	    }
217	
218	    @FunctionalInterface
219	    private interface ErrorHandler {
220	        void handle(Exception ex);
221	    }
222	}
