3	import org.junit.jupiter.api.DisplayName;
4	import org.junit.jupiter.api.Test;
5	
6	import java.math.BigDecimal;
7	
8	import static org.junit.jupiter.api.Assertions.assertEquals;
9	import static org.junit.jupiter.api.Assertions.assertFalse;
10	import static org.junit.jupiter.api.Assertions.assertTrue;
11	
12	/**
13	 * 改品种纯规则单元测试：克重差、灰分级差、工艺窗口边界、过渡料长度、正品门槛边界。
14	 */
15	class TransitionRulesTest {
16	
17	    @Test
18	    @DisplayName("克重差恰 10%（70→77）判为直切，超出（70→80）须停机清洗")
19	    void directSwitchBoundaryAtExactlyTenPercent() {
20	        BigDecimal exactTen = TransitionRules.basisWeightDeltaPct(new BigDecimal("70.00"),
21	                new BigDecimal("77.00"));
22	        assertEquals(0, new BigDecimal("10.0000").compareTo(exactTen));
23	        assertTrue(TransitionRules.isDirectSwitch(exactTen), "恰 10% 必须直切");
24	
25	        BigDecimal beyond = TransitionRules.basisWeightDeltaPct(new BigDecimal("70.00"),
26	                new BigDecimal("80.00"));
27	        assertEquals(0, new BigDecimal("14.2857").compareTo(beyond));
28	        assertFalse(TransitionRules.isDirectSwitch(beyond), "超出 10% 须停机清洗");
29	
30	        // 略低于 10% 也直切。
31	        BigDecimal below = TransitionRules.basisWeightDeltaPct(new BigDecimal("77.00"),
32	                new BigDecimal("84.00"));
33	        assertEquals(0, new BigDecimal("9.0909").compareTo(below));
34	        assertTrue(TransitionRules.isDirectSwitch(below));
35	    }
36	
37	    @Test
38	    @DisplayName("灰分等级差恰 2 级合法直切不冲洗，超过 2 级须冲洗网部")
39	    void ashLevelBoundaryAtExactlyTwo() {
40	        assertEquals(2, TransitionRules.ashLevelDelta(1, 3));
41	        assertFalse(TransitionRules.needsWireFlush(2), "恰 2 级不得冲洗网部");
42	        assertTrue(TransitionRules.needsWireFlush(3), "差 3 级须冲洗网部");
43	        assertFalse(TransitionRules.needsWireFlush(1));
44	        assertFalse(TransitionRules.needsWireFlush(0));
45	    }
46	
47	    @Test
48	    @DisplayName("工艺窗口恰在上下边界视为合格，越界拒绝")
49	    void processWindowBoundariesInclusive() {
50	        BigDecimal min = new BigDecimal("830.000");
51	        BigDecimal max = new BigDecimal("1030.000");
52	        assertTrue(TransitionRules.withinWindow(min, min, max), "下边界合格");
53	        assertTrue(TransitionRules.withinWindow(max, min, max), "上边界合格");
54	        assertTrue(TransitionRules.withinWindow(new BigDecimal("900.000"), min, max));
55	        assertFalse(TransitionRules.withinWindow(new BigDecimal("829.999"), min, max));
56	        assertFalse(TransitionRules.withinWindow(new BigDecimal("1030.001"), min, max));
57	    }
58	
59	    @Test
60	    @DisplayName("过渡料长度=车速×切换时间/60")
61	    void transitionLengthFormula() {
62	        // 900 m/min × 120 s / 60 = 1800 m
63	        assertEquals(0, new BigDecimal("1800.000").compareTo(
64	                TransitionRules.transitionLengthM(new BigDecimal("900.000"), 120)));
65	        // 830 m/min × 61 s / 60 = 843.833 m（HALF_UP）
66	        assertEquals(0, new BigDecimal("843.833").compareTo(
67	                TransitionRules.transitionLengthM(new BigDecimal("830.000"), 61)));
68	    }
