14	
15	import static org.hamcrest.Matchers.hasSize;
16	import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
17	import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
18	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
19	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
20	
21	/**
22	 * REST API 契约测试：申请 201、同键重放 200、异参 409、判定/执行/处置链路与复算接口。
23	 */
24	@AutoConfigureMockMvc
25	@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.MOCK)
26	@Import(AbstractIntegrationTest.FixedClockConfiguration.class)
27	class TransitionApiTest extends AbstractIntegrationTest {
28	
29	    @Autowired
30	    private MockMvc mockMvc;
31	    @Autowired
32	    private JdbcTemplate jdbc;
33	
34	    @BeforeEach
35	    void clean() {
36	        cleanBusinessTables(jdbc);
37	    }
38	
39	    @Test
40	    @DisplayName("HTTP全链路：申请201→重放200→异参409→判定→执行→处置→复算")
41	    void fullHttpFlow() throws Exception {
42	        // 申请：201
43	        String applyBody = """
44	                {"requestId":"api-1","paperMachine":"PM-W1","fromGrade":"G-A4-70","toGrade":"G-A4-77"}
45	                """;
46	        String response = mockMvc.perform(post("/api/transitions/orders")
47	                        .contentType(MediaType.APPLICATION_JSON).content(applyBody))
48	                .andExpect(status().isCreated())
49	                .andExpect(jsonPath("$.replayed").value(false))
50	                .andExpect(jsonPath("$.data.status").value("APPLIED"))
51	                .andReturn().getResponse().getContentAsString();
52	
53	        String orderNo = com.jayway.jsonpath.JsonPath.read(response, "$.data.orderNo");
54	
55	        // 同键同参重放：200 + replayed=true
56	        mockMvc.perform(post("/api/transitions/orders")
57	                        .contentType(MediaType.APPLICATION_JSON).content(applyBody))
58	                .andExpect(status().isOk())
59	                .andExpect(jsonPath("$.replayed").value(true))
60	                .andExpect(jsonPath("$.data.orderNo").value(orderNo));
61	
62	        // 同键异参：409
63	        mockMvc.perform(post("/api/transitions/orders")
64	                        .contentType(MediaType.APPLICATION_JSON)
65	                        .content("""
66	                                {"requestId":"api-1","paperMachine":"PM-W1","fromGrade":"G-A4-70","toGrade":"G-A4-80"}
67	                                """))
68	                .andExpect(status().isConflict());
69	
70	        // 判定：恰 10% 直切、灰分恰 2 级不冲洗
71	        mockMvc.perform(post("/api/transitions/orders/{no}/decide", orderNo))
72	                .andExpect(status().isOk())
73	                .andExpect(jsonPath("$.directSwitch").value(true))
74	                .andExpect(jsonPath("$.wireFlush").value(false))
75	                .andExpect(jsonPath("$.basisWeightDeltaPct").value(10.0000));
76	
77	        // 越界执行：400（单据仍为 DECIDED，先校验工艺窗口）
78	        mockMvc.perform(post("/api/transitions/orders/{no}/execute", orderNo)
79	                        .contentType(MediaType.APPLICATION_JSON)
80	                        .content("""
81	                                {"machineSpeedMMin":819.999,"stockConsistencyPct":0.850,"switchTimeSec":120}
82	                                """))
83	                .andExpect(status().isBadRequest());
84	
85	        // 执行：窗口下边界参数合格；过渡料 820×120/60=1640
86	        mockMvc.perform(post("/api/transitions/orders/{no}/execute", orderNo)
87	                        .contentType(MediaType.APPLICATION_JSON)
88	                        .content("""
89	                                {"machineSpeedMMin":820.000,"stockConsistencyPct":0.850,"switchTimeSec":120}
90	                                """))
91	                .andExpect(status().isOk())
92	                .andExpect(jsonPath("$.status").value("EXECUTED"))
93	                .andExpect(jsonPath("$.transitionLengthM").value(1640.000));
94	
95	        // 过渡料处置：两卷强制降级
96	        mockMvc.perform(post("/api/transitions/orders/{no}/dispose", orderNo)
97	                        .contentType(MediaType.APPLICATION_JSON)
98	                        .content("""
99	                                {"rolls":[{"rollNo":"RW-1","lengthM":800.000},{"rollNo":"RW-2","lengthM":840.000}]}
100	                                """))
101	                .andExpect(status().isOk())
102	                .andExpect(jsonPath("$.status").value("DISPOSED"));
103	
104	        mockMvc.perform(get("/api/transitions/rolls/RW-1"))
105	                .andExpect(status().isOk())
106	                .andExpect(jsonPath("$.verdict").value("DOWNGRADED"))
107	                .andExpect(jsonPath("$.warehouseStatus").value("NON_GENUINE"))
108	                .andExpect(jsonPath("$.chain", hasSize(1)));
109	
110	        // 复算：记录长度=重算长度，卷明细两卷
111	        mockMvc.perform(get("/api/transitions/orders/{no}/recompute", orderNo))
112	                .andExpect(status().isOk())
113	                .andExpect(jsonPath("$.recordedTransitionLengthM").value(1640.000))
114	                .andExpect(jsonPath("$.recomputedTransitionLengthM").value(1640.000))
115	                .andExpect(jsonPath("$.sumRollLengthM").value(1640.000))
